    if(api=="wx.setKeepScreenOn"){if(!SetThreadExecutionState(payload.value("keepScreenOn",false)?ES_CONTINUOUS|ES_DISPLAY_REQUIRED:ES_CONTINUOUS))throw std::system_error(GetLastError(),std::system_category());done(call,api);return true;}
